#include <immintrin.h>
#include <stdio.h>
#include <stdint.h>

int main() {
    uint8_t rowIn[32] = {
        10, 20, 30, 255, 11, 21, 31, 255,
        12, 22, 32, 255, 13, 23, 33, 255,
        14, 24, 34, 255, 15, 25, 35, 255,
        16, 26, 36, 255, 17, 27, 37, 255
    };
    __m256i pix = _mm256_loadu_si256((__m256i*)rowIn);
    __m256i mask = _mm256_set1_epi32(0xFF);
    __m256i r = _mm256_and_si256(pix, mask);
    __m256i g = _mm256_and_si256(_mm256_srli_epi32(pix, 8), mask);
    __m256i b = _mm256_and_si256(_mm256_srli_epi32(pix, 16), mask);

