    _mm256_storeu_si256((__m256i*)gv, g);
    _mm256_storeu_si256((__m256i*)bv, b);

    for (int i=0; i<8; ++i) {
        printf("%d %d %d\n", rv[i], gv[i], bv[i]);
    }
    return 0;
}
