#include <immintrin.h>
#include <stdio.h>
#include <stdint.h>

int main() {
    int16_t a[8] = {10, 20, 30, 40, 50, 60, 70, 80};
    int16_t b[8] = {15, 25, 35, 45, 55, 65, 75, 85};
    int16_t shift[8] = {16384, 16384, 8192, 8192, 0, 0, 32767, 32767};
    int16_t SHIFT_BITS = 15;

    // We want to pack a and b into 32-bit integers
    __m256i va = _mm256_loadu_si256((__m256i*)a); // wait, this is 8x16-bit = 128 bit.
    // For 8 pixels, we need a __m128i for 'a' and a __m128i for 'b'.
    __m128i ma = _mm_loadu_si128((__m128i*)a);
    __m128i mb = _mm_loadu_si128((__m128i*)b);
    __m128i mshift = _mm_loadu_si128((__m128i*)shift);

    // unpack 'a' and 'b' to pair them:
    // a0 b0 a1 b1 ...
    __m128i pair_lo = _mm_unpacklo_epi16(ma, mb); // a0 b0 a1 b1 a2 b2 a3 b3
    __m128i pair_hi = _mm_unpackhi_epi16(ma, mb); // a4 b4 a5 b5 a6 b6 a7 b7
    __m256i pairs = _mm256_inserti128_si256(_mm256_castsi128_si256(pair_lo), pair_hi, 1);

    // weights: w0 = (1<<SHIFT_BITS) - shift, w1 = shift
    __m128i w0 = _mm_sub_epi16(_mm_set1_epi16(1 << SHIFT_BITS), mshift);
    __m128i weight_lo = _mm_unpacklo_epi16(w0, mshift);
    __m128i weight_hi = _mm_unpackhi_epi16(w0, mshift);
    __m256i weights = _mm256_inserti128_si256(_mm256_castsi128_si256(weight_lo), weight_hi, 1);

    __m256i res32 = _mm256_madd_epi16(pairs, weights);
    res32 = _mm256_srai_epi32(res32, SHIFT_BITS); // result as 32-bit

    // pack back to 16-bit
    // res32 has 8 32-bit integers. Pack to 8 16-bit.
    __m128i res16 = _mm256_castsi256_si128(_mm256_permute4x64_epi64(
