    __m128i diff = _mm_sub_epi16(mb, ma);

    // unpack with 0
    __m128i zero = _mm_setzero_si128();
    __m128i diff_lo = _mm_unpacklo_epi16(diff, zero); // (b-a)0, 0, (b-a)1, 0...
    __m128i diff_hi = _mm_unpackhi_epi16(diff, zero);
