static inline __m128i interp_8(__m128i ma, __m128i mb, __m256i mshift) {
    __m128i diff = _mm_sub_epi16(mb, ma);
    __m128i zero = _mm_setzero_si128();

    __m128i diff_lo = _mm_unpacklo_epi16(diff, zero); // signed expansion is fine if diff is positive? Wait, diff can be negative!
